figures/fig_learning_curve_t1.pdf.block:
\begin{figure}[!t]
  \centering
  \includegraphics[width=\columnwidth,height=1.45in,keepaspectratio]{figures/fig_learning_curve_t1.pdf}
  \caption{Task 1 half-chain entropy: mean test $R^2$ vs.\ training size $N_{\mathrm{tr}}$ across 20 fixed seeds. Bands: 95\% bootstrap CI. PQK-2nn tracks FQ and classical E (raw); single-body PQK-1 saturates $\approx 0.04$--$0.10$ $R^2$ lower.}
  \label{fig:t1_lc}
\end{figure}

figures/fig_shots.pdf.block:
\begin{figure}[!t]
  \centering
  \includegraphics[width=\columnwidth,height=1.45in,keepaspectratio]{figures/fig_shots.pdf}
  \caption{FQ test $R^2$ vs.\ total swap-test shots $S$ ($N_{\mathrm{tr}}=40$, 20 seeds). Solid: unclipped indefinite Gram (non-PSD in 20/20 seeds); dashed: eigenvalue-clipped. Feature-arm costs ($480S$--$720S$) are over an order of magnitude lower. Bands: 95\% bootstrap CI.}
  \label{fig:shots}
\end{figure}

